import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'1c9dmLesD1G0pPTCYrjt',titulo:'Kit 2 Suporte Porta Shampoo Sabonete Prateleira Banheiro Adesivo Parede Sem Furar Box Luxo Cor Preto Homeroarte',listing:'MLB4951174502'},{id:'1Iyoc1zKTUsDEQGbvIM3',titulo:'Inalador Nebulizador Aero Tech Portátil Tec. Mesh Relaxmedic',listing:'MLB4435213175'},{id:'1VMzq0ovRkap3dGQ7ikC',titulo:'Fritadeira Air Fryer Philco 16 Litros Paf16c Preto 220v',listing:'MLB4604524273'}];
test('triagem48 preserva preço identidade variante e afiliado e recusa outro anúncio/acessório',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('Homeroarte não garante carga parede universal ou retirada sem marcas',()=>{const x=correctProductData(rows[0]);assert.match(x.comentario,/não garante fixação em toda parede/);assert.match(x.comentario,/Não há limite de peso confirmado/);assert.doesNotMatch(x.pros,/\d+\s*kg|luxo|garant|sem marcas|inox/i);});
test('Aero Tech não prescreve tratamento ou confirma recursos sem fonte',()=>{const x=correctProductData(rows[1]);assert.match(x.comentario,/não é indicação clínica individual/);assert.match(x.comentario,/display.*não foram confirmados/);assert.match(x.comentario,/não escolhe medicamentos, doses ou tratamento/);assert.doesNotMatch(x.pros,/cura|eficácia|seguro|qualquer|asma|bronquite|\d+\s*minutos/i);});
test('PAF16C mantém 220 V e não promete rapidez consumo ou porções',()=>{const x=correctProductData(rows[2]);assert.equal(x.titulo,rows[2].titulo);assert.match(x.comentario,/Não tratamos esta unidade como bivolt/);assert.match(x.comentario,/Não prometemos preparo mais rápido/);assert.doesNotMatch(x.pros,/ideal|robust|efici|econom|rápid|famílias|\d+\s*porções/i);});
